import{_ as a,c as n,o as s,aN as r}from"./chunks/framework.DXgs1r1w.js";const h=JSON.parse('{"title":"UDP","description":"","frontmatter":{"date":"2024-10-28T15:14:01.000Z","title":"UDP","permalink":"/pages/efcf01","categories":["Linux","计算机网络"]},"headers":[],"relativePath":"Linux/计算机网络/UDP.md","filePath":"Linux/计算机网络/UDP.md","lastUpdated":1785476990000}'),e={name:"Linux/计算机网络/UDP.md"};function d(l,t,o,p,i,P){return s(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h1><p>&lt;Golang底层原理剖析&gt; &lt;Golang专家编程&gt;</p><h2 id="udp-协议概述" tabindex="-1">UDP 协议概述 <a class="header-anchor" href="#udp-协议概述" aria-label="Permalink to &quot;UDP 协议概述&quot;">​</a></h2><p>UDP（User Datagram Protocol，<strong>用户数据报协议</strong>）是 TCP/IP 协议族中传输层的两个核心协议之一，与 TCP 并列。它在 IP 协议（网络层）之上提供<strong>无连接、不可靠、尽最大努力交付</strong>的数据报传输服务。</p><p>UDP 的设计目标非常纯粹：<strong>尽可能快地转发数据，把可靠性、流量控制、拥塞控制等职责全部交给应用层</strong>。因此它在实时性要求高、能容忍少量丢包的场景中不可替代。</p><h3 id="udp-的主要特点" tabindex="-1">UDP 的主要特点 <a class="header-anchor" href="#udp-的主要特点" aria-label="Permalink to &quot;UDP 的主要特点&quot;">​</a></h3><ul><li><strong>无连接</strong>：发送数据前不需要建立连接，也不维护连接状态，发送结束也不需要释放连接。每台主机可以同时向多个接收方发送，也允许接收多个发送方的数据（支持一对一、一对多、多对一、多对多）。</li><li><strong>不可靠交付</strong>：不保证数据报一定能到达、不保证按序到达、不保证只到达一次。没有确认、重传、序号机制。</li><li><strong>面向报文</strong>：UDP 对应用层交下来的报文<strong>既不合并也不拆分</strong>，保留报文边界。一次发送对应一次接收（接收方 <code>recvfrom</code> 一次拿到一个完整数据报）。应用层需要自己控制合适的报文大小。</li><li><strong>没有拥塞控制</strong>：无论网络是否拥塞，UDP 都以恒定速率发送。这既是优点（低延迟）也是隐患（可能加剧网络拥塞）。</li><li><strong>首部开销极小</strong>：固定只有 <strong>8 字节</strong>（TCP 首部至少 20 字节），无连接状态，处理简单，传输效率高。</li></ul><h2 id="udp-报文格式" tabindex="-1">UDP 报文格式 <a class="header-anchor" href="#udp-报文格式" aria-label="Permalink to &quot;UDP 报文格式&quot;">​</a></h2><p>UDP 数据报由<strong>首部</strong>和<strong>数据</strong>两部分组成，首部固定 8 字节：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|          源端口号            |          目的端口号            |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|            长度              |          检验和                |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                            数据 ...                          |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>源端口（Source Port）</td><td>16 位</td><td>发送方端口号，<strong>可选</strong>。不需要对方回信时可填 0</td></tr><tr><td>目的端口（Destination Port）</td><td>16 位</td><td>接收方端口号，<strong>必填</strong>。接收方据此将数据交给对应进程</td></tr><tr><td>长度（Length）</td><td>16 位</td><td>UDP 数据报总长度（首部 8 字节 + 数据），单位为字节，最小为 8</td></tr><tr><td>检验和（Checksum）</td><td>16 位</td><td><strong>可选</strong>。用于检测传输错误，计算时涵盖首部、数据和「伪首部」</td></tr></tbody></table><blockquote><p>与 TCP 不同，UDP 的端口号字段**没有「序号」「确认号」「窗口」「标志位」**等字段，因此 UDP 首部非常简单。</p></blockquote><h2 id="udp-校验和与伪首部" tabindex="-1">UDP 校验和与伪首部 <a class="header-anchor" href="#udp-校验和与伪首部" aria-label="Permalink to &quot;UDP 校验和与伪首部&quot;">​</a></h2><p>UDP 的检验和是可选的（IPv4 下字段为 0 表示未计算；IPv6 下校验和<strong>强制</strong>必须计算）。它采用与 TCP 相同的<strong>二进制反码求和</strong>算法。</p><p>计算校验和时，除了 UDP 首部和数据，还会拼上一个<strong>伪首部（Pseudo Header）</strong>。伪首部<strong>并不真实传输</strong>，仅用于校验，目的是让 UDP 能校验「数据报是否送到了正确的主机和协议」：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 0               1               2               3</span></span>
<span class="line"><span> 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7 0 1 2 3 4 5 6 7</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                      32 位源 IP 地址                         |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>|                     32 位目的 IP 地址                       |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span>
<span class="line"><span>| 保留(0) | 协议(17) |            UDP 长度                     |</span></span>
<span class="line"><span>+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li>协议号 <strong>17</strong> 表示 UDP（TCP 为 6），用于确认上层协议身份。</li><li>如果接收方校验和出错，UDP 直接<strong>丢弃该数据报</strong>，不发送任何差错通知（这再次体现了「不可靠」）。</li><li>如果发送方未计算校验和（字段为 0），接收方<strong>不会</strong>因校验和字段为 0 而丢弃，而是跳过校验。</li></ul><h2 id="udp-为什么是不可靠的" tabindex="-1">UDP 为什么是不可靠的 <a class="header-anchor" href="#udp-为什么是不可靠的" aria-label="Permalink to &quot;UDP 为什么是不可靠的&quot;">​</a></h2><p>UDP 之所以「不可靠」，是因为它在协议层面<strong>刻意不做</strong>以下事情：</p><ul><li><strong>无确认机制</strong>：发送方发出数据报后不会等待接收方确认，也无从得知对方是否收到。</li><li><strong>无重传机制</strong>：数据报丢失、重复、乱序时，UDP 不会重发，也不做纠正。</li><li><strong>无流量控制</strong>：发送方不考虑接收方缓冲区是否溢出，可能「发爆」接收方。</li><li><strong>无拥塞控制</strong>：网络拥塞时 UDP 仍按原速率发送，可能雪上加霜。</li></ul><p>这些「缺失」并非缺陷，而是<strong>设计取舍</strong>：换来了极低的首部开销和最低的延迟。可靠性如果需要，就由<strong>应用层协议</strong>自己实现（见下文）。</p><h2 id="udp-适用场景" tabindex="-1">UDP 适用场景 <a class="header-anchor" href="#udp-适用场景" aria-label="Permalink to &quot;UDP 适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>原因</th></tr></thead><tbody><tr><td>实时音视频（直播、通话、会议）</td><td>容忍少量丢包，但无法容忍重传带来的几百毫秒延迟</td></tr><tr><td>实时游戏 / 多人竞技</td><td>延迟敏感，丢包比卡顿更可接受</td></tr><tr><td>广播 / 组播</td><td>TCP 是点对点连接，UDP 天然支持一对多</td></tr><tr><td>海量小请求（DNS、DHCP 查询）</td><td>一次请求一次响应，建连开销不划算</td></tr><tr><td>高速内网传输（如 TFTP、数据库同步）</td><td>链路质量好，可靠性由应用保证更高效</td></tr><tr><td>需要自定义可靠性的场景</td><td>应用层可在 UDP 上实现比 TCP 更贴合业务的可靠机制（如 QUIC、KCP）</td></tr></tbody></table><h2 id="基于-udp-的典型应用协议" tabindex="-1">基于 UDP 的典型应用协议 <a class="header-anchor" href="#基于-udp-的典型应用协议" aria-label="Permalink to &quot;基于 UDP 的典型应用协议&quot;">​</a></h2><ul><li><strong>DNS（域名解析）</strong>：通常基于 UDP 53 端口，一次查询一次响应，超时后才可能走 TCP。</li><li><strong>DHCP（动态主机配置）</strong>：客户端初始没有 IP，无法建立 TCP 连接，只能用广播 UDP。</li><li><strong>TFTP（简单文件传输）</strong>：基于 UDP 的轻量文件传输，自己实现简单确认重传。</li><li><strong>SNMP（简单网络管理）</strong>：网络设备监控，UDP 161/162 端口。</li><li><strong>RIP（路由信息协议）</strong>：基于 UDP 520 端口的距离矢量路由协议。</li><li><strong>RTP / RTCP（实时传输协议）</strong>：音视频流媒体载体，常与 UDP 配合。</li><li><strong>QUIC（HTTP/3 的底层）</strong>：在 UDP 之上实现可靠、有序、0-RTT、拥塞控制，取代 TCP+TLS。</li></ul><h2 id="udp-上如何实现「可靠传输」" tabindex="-1">UDP 上如何实现「可靠传输」 <a class="header-anchor" href="#udp-上如何实现「可靠传输」" aria-label="Permalink to &quot;UDP 上如何实现「可靠传输」&quot;">​</a></h2><p>当应用确实需要可靠，但又想保留 UDP 的低延迟/灵活性时，常见的做法是<strong>在应用层自己做可靠性</strong>，典型代表：</p><h3 id="_1-quic-http-3" tabindex="-1">1. QUIC（HTTP/3） <a class="header-anchor" href="#_1-quic-http-3" aria-label="Permalink to &quot;1. QUIC（HTTP/3）&quot;">​</a></h3><p>Google 提出、现为 HTTP/3 标准。在 UDP 之上实现：</p><ul><li>可靠、有序传输（类 TCP）</li><li>0-RTT / 1-RTT 连接建立（避免 TCP+TLS 的多轮握手）</li><li>多路复用且<strong>无队头阻塞</strong>（每个流独立）</li><li>连接迁移（切换网络 IP 变化不断连）</li></ul><h3 id="_2-kcp" tabindex="-1">2. KCP <a class="header-anchor" href="#_2-kcp" aria-label="Permalink to &quot;2. KCP&quot;">​</a></h3><p>一种以<strong>牺牲带宽换取低延迟</strong>的可靠 UDP 方案，通过快速重传、忽略丢包率换速度，广泛用于游戏、弱网传输。</p><h3 id="_3-webrtc-srtp" tabindex="-1">3. WebRTC / SRTP <a class="header-anchor" href="#_3-webrtc-srtp" aria-label="Permalink to &quot;3. WebRTC / SRTP&quot;">​</a></h3><p>实时音视频通信框架，媒体数据走 UDP（RTP/SRTP），信令走其他通道；丢包时通过前向纠错（FEC）、丢帧而非重传来保证流畅。</p><h3 id="_4-自研可靠-udp" tabindex="-1">4. 自研可靠 UDP <a class="header-anchor" href="#_4-自研可靠-udp" aria-label="Permalink to &quot;4. 自研可靠 UDP&quot;">​</a></h3><p>游戏、IM 常基于 UDP 自研：加入序号、确认、超时重传、拥塞控制等子集，只保留业务需要的那部分，做到「刚好可靠」。</p><h2 id="udp-与-tcp-对比" tabindex="-1">UDP 与 TCP 对比 <a class="header-anchor" href="#udp-与-tcp-对比" aria-label="Permalink to &quot;UDP 与 TCP 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接性</td><td>面向连接（三次握手、四次挥手）</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠（确认、重传、序号）</td><td>不可靠（尽最大努力交付）</td></tr><tr><td>顺序性</td><td>保证按序到达</td><td>不保证顺序</td></tr><tr><td>数据边界</td><td>字节流，无消息边界（可能粘包/拆包）</td><td>保留报文边界（面向报文）</td></tr><tr><td>速度</td><td>较慢（握手、确认、控制开销）</td><td>较快</td></tr><tr><td>首部开销</td><td>20~60 字节</td><td>8 字节</td></tr><tr><td>流量控制</td><td>有（滑动窗口）</td><td>无</td></tr><tr><td>拥塞控制</td><td>有（慢启动、拥塞避免等）</td><td>无</td></tr><tr><td>通信模式</td><td>仅一对一</td><td>一对一、一对多、多对多、广播/组播</td></tr><tr><td>适用场景</td><td>文件传输、网页、邮件</td><td>音视频、DNS、游戏、实时通信</td></tr></tbody></table><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q1：UDP 会粘包/拆包吗？</strong> 不会。UDP 是「面向报文」的，保留了应用层交付的报文边界：发送方一次 <code>sendto</code> 对应接收方一次 <code>recvfrom</code>，不会合并也不会拆分。所谓「UDP 粘包」通常是应用层把多个逻辑消息塞进了一个数据报，或接收缓冲区一次读多了——但每个 UDP 数据报本身仍是独立的。</p><p><strong>Q2：UDP 最大能发多大？</strong> 理论上 UDP 长度字段 16 位，最大 65535 字节，减去 8 字节首部，单包数据最大 <strong>65527 字节</strong>。但受底层 <strong>MTU</strong>（以太网通常 1500 字节）限制，超过 MTU 会在 IP 层分片，分片任一片丢失整包作废，因此<strong>实际建议将数据控制在 1472 字节（1500 - 20 IP - 8 UDP）以内</strong>以避免分片。</p><p><strong>Q3：UDP 不是不可靠吗，为什么 DNS 用 UDP？</strong> DNS 查询通常一次请求对应一次响应，数据量小、对延迟敏感；若用 TCP 要多一次握手往返，代价过高。DNS 在响应超时会改用 TCP，且重要区传输（AXFR）本就走 TCP——即「默认 UDP 追求快，必要时退化到 TCP 保证可靠」。</p><p><strong>Q4：如何对 UDP 做「限流/防拥塞」？</strong> UDP 自身没有拥塞控制，若大量使用（如自研可靠 UDP、QUIC、视频推流），需在<strong>应用层</strong>实现拥塞控制（如 QUIC 自带 BBR-like 算法、KCP 的流控），否则容易把网络打满。</p>`,43)])])}const g=a(e,[["render",d]]);export{h as __pageData,g as default};
